package com.company.platform.aigateway.orchestration;import java.util.*;import org.springframework.stereotype.Component;@Component public class PluginResolver{private final PluginRegistry registry;public PluginResolver(PluginRegistry r){registry=r;}public Optional<PluginDescriptor> resolve(UUID tenant,String name){return registry.list(tenant).stream().filter(x->x.name().equals(name)&&"REGISTERED".equals(x.status())).findFirst();}}
